"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[988],{2485:(e,n,s)=>{s.r(n),s.d(n,{data:()=>a});const a={key:"v-d0736a32",path:"/usage/",title:"Usage",lang:"en-US",frontmatter:{},excerpt:"",headers:[{level:2,title:"Pattern 1 — The simplest usage",slug:"pattern-1-—-the-simplest-usage",children:[]},{level:2,title:"Pattern 2 — Create multiple files at once",slug:"pattern-2-—-create-multiple-files-at-once",children:[]},{level:2,title:"Pattern 3 — Specify the file extension",slug:"pattern-3-—-specify-the-file-extension",children:[]},{level:2,title:"Pattern 4 — Generate actual image files",slug:"pattern-4-—-generate-actual-image-files",children:[{level:3,title:"Specify the image size with -s",slug:"specify-the-image-size-with-s",children:[]}]},{level:2,title:"Pattern 5 — Create files inside a directory",slug:"pattern-5-—-create-files-inside-a-directory",children:[]},{level:2,title:"Pattern 6 — Create files in multiple directories",slug:"pattern-6-—-create-files-in-multiple-directories",children:[]},{level:2,title:"Pattern 7 — Create a deeply nested directory tree",slug:"pattern-7-—-create-a-deeply-nested-directory-tree",children:[]},{level:2,title:"Pattern 8 — Place files in every level with --each",slug:"pattern-8-—-place-files-in-every-level-with-each",children:[]},{level:2,title:"Pattern 9 — Use shell brace expansion",slug:"pattern-9-—-use-shell-brace-expansion",children:[]},{level:2,title:"Pattern 10 — Brace expansion with --each",slug:"pattern-10-—-brace-expansion-with-each",children:[]},{level:2,title:"Pattern 11 — Images into multiple directories",slug:"pattern-11-—-images-into-multiple-directories",children:[]},{level:2,title:"Pattern 12 — Special character file names",slug:"pattern-12-—-special-character-file-names",children:[{level:3,title:"Symbol-free names",slug:"symbol-free-names",children:[]},{level:3,title:"Names with spaces",slug:"names-with-spaces",children:[]},{level:3,title:"Names with 2-byte (Japanese) characters",slug:"names-with-2-byte-japanese-characters",children:[]}]},{level:2,title:"Pattern 13 — Preview with --cold-run",slug:"pattern-13-—-preview-with-cold-run",children:[]},{level:2,title:"Options reference",slug:"options-reference",children:[]}],filePathRelative:"usage/README.md",git:{updatedTime:1779340062e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:4}]}}},3817:(e,n,s)=>{s.r(n),s.d(n,{default:()=>t});const a=(0,s(6252).uE)('<h1 id="usage" tabindex="-1"><a class="header-anchor" href="#usage" aria-hidden="true">#</a> Usage</h1><h2 id="pattern-1-—-the-simplest-usage" tabindex="-1"><a class="header-anchor" href="#pattern-1-—-the-simplest-usage" aria-hidden="true">#</a> Pattern 1 — The simplest usage</h2><p>Run <code>dammy.sh</code> with no arguments. One <code>.txt</code> file with a random name is created in the current directory.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh\n$ tree\n<span class="token builtin class-name">.</span>\n└── 0hi<span class="token punctuation">)</span>_mB.wf.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="pattern-2-—-create-multiple-files-at-once" tabindex="-1"><a class="header-anchor" href="#pattern-2-—-create-multiple-files-at-once" aria-hidden="true">#</a> Pattern 2 — Create multiple files at once</h2><p>Use <code>-n</code> to create several files in one shot.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">5</span>\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token variable">$qxT2</span>+_&#39;uW.txt\n├── Hk3mNzKs.txt\n├── pdK:gXwu.Q.txt\n├── tl4NUT<span class="token punctuation">(</span>q7b.txt\n└── Vu8nXjBsLe.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="pattern-3-—-specify-the-file-extension" tabindex="-1"><a class="header-anchor" href="#pattern-3-—-specify-the-file-extension" aria-hidden="true">#</a> Pattern 3 — Specify the file extension</h2><p>Use <code>-e</code> to generate files with any extension.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e csv\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token punctuation">;</span>mSu179.QE.csv\n├── JGElYbT3d<span class="token punctuation">\\</span>.csv\n└── tyP+<span class="token punctuation">\\</span>woXGQ.csv\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="pattern-4-—-generate-actual-image-files" tabindex="-1"><a class="header-anchor" href="#pattern-4-—-generate-actual-image-files" aria-hidden="true">#</a> Pattern 4 — Generate actual image files</h2><p>When you specify an image format, dammy generates real image files using ImageMagick — a gray canvas with the size printed at the center. Perfect as placeholder images for web development.</p><p>Supported: <code>jpg</code> <code>jpeg</code> <code>png</code> <code>gif</code> <code>bmp</code> <code>tiff</code> <code>webp</code></p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg\n$ tree\n<span class="token builtin class-name">.</span>\n├── 100x100_1.jpg\n├── 100x100_2.jpg\n└── 100x100_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="specify-the-image-size-with-s" tabindex="-1"><a class="header-anchor" href="#specify-the-image-size-with-s" aria-hidden="true">#</a> Specify the image size with <code>-s</code></h3><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">4</span> -e png -s 320x240\n$ tree\n<span class="token builtin class-name">.</span>\n├── 320x240_1.png\n├── 320x240_2.png\n├── 320x240_3.png\n└── 320x240_4.png\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="pattern-5-—-create-files-inside-a-directory" tabindex="-1"><a class="header-anchor" href="#pattern-5-—-create-files-inside-a-directory" aria-hidden="true">#</a> Pattern 5 — Create files inside a directory</h2><p>Pass a directory path as an argument. The directory is created automatically if it does not exist.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> work\n$ tree\n<span class="token builtin class-name">.</span>\n└── work\n    ├── 9BcTRkOgLw.txt\n    ├── J<span class="token punctuation">(</span>q<span class="token operator">=</span>E.@Ma0.txt\n    └── x<span class="token operator">&amp;</span>bY,2s<span class="token punctuation">)</span>qg.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="pattern-6-—-create-files-in-multiple-directories" tabindex="-1"><a class="header-anchor" href="#pattern-6-—-create-files-in-multiple-directories" aria-hidden="true">#</a> Pattern 6 — Create files in multiple directories</h2><p>Pass multiple paths to populate several directories at once.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> assets/images assets/css assets/js\n$ tree\n<span class="token builtin class-name">.</span>\n└── assets\n    ├── css\n    │   ├── 4Jd8wNkR.txt\n    │   └── hR2nQvLw.txt\n    ├── images\n    │   ├── 3Kp9mXtA.txt\n    │   └── uZ7bYcFe.txt\n    └── js\n        ├── aX1mBqTy.txt\n        └── sF6vUzPc.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><hr><h2 id="pattern-7-—-create-a-deeply-nested-directory-tree" tabindex="-1"><a class="header-anchor" href="#pattern-7-—-create-a-deeply-nested-directory-tree" aria-hidden="true">#</a> Pattern 7 — Create a deeply nested directory tree</h2><p>Slashes create intermediate directories automatically.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> project/src/components\n$ tree\n<span class="token builtin class-name">.</span>\n└── project\n    └── src\n        └── components\n            ├── :w9a@DmC~N.txt\n            └── Ab3Kp<span class="token operator">!</span>mQvX.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="pattern-8-—-place-files-in-every-level-with-each" tabindex="-1"><a class="header-anchor" href="#pattern-8-—-place-files-in-every-level-with-each" aria-hidden="true">#</a> Pattern 8 — Place files in every level with <code>--each</code></h2><p><code>--each</code> creates files not just in the deepest directory, but in every directory along the path.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> project/src/components --each\n$ tree\n<span class="token builtin class-name">.</span>\n└── project\n    ├── Pq7mNzKsYo.txt\n    ├── Vu8nXjBsLe.txt\n    └── src\n        ├── <span class="token operator">&amp;</span>dGzWh<span class="token operator">!</span>F2f.txt\n        ├── Hk3mNzKs.txt\n        └── components\n            ├── %<span class="token punctuation">\\</span>&#39;fRw2z,h.txt\n            └── yLv*lTz<span class="token punctuation">\\</span>BG.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><hr><h2 id="pattern-9-—-use-shell-brace-expansion" tabindex="-1"><a class="header-anchor" href="#pattern-9-—-use-shell-brace-expansion" aria-hidden="true">#</a> Pattern 9 — Use shell brace expansion</h2><p>Combine dammy with the shell&#39;s brace expansion to build branching trees.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> src/<span class="token punctuation">{</span>components,pages,utils<span class="token punctuation">}</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── src\n    ├── components\n    │   ├── Kd4pRmTzWq.txt\n    │   └── Vu8nXjBsLe.txt\n    ├── pages\n    │   ├── 9k~MYXwoH<span class="token operator">!</span>.txt\n    │   └── ey<span class="token punctuation">\\</span>%lAFx2V.txt\n    └── utils\n        ├── Ab3Kp<span class="token operator">!</span>mQvX.txt\n        └── :w9a@DmC~N.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><hr><h2 id="pattern-10-—-brace-expansion-with-each" tabindex="-1"><a class="header-anchor" href="#pattern-10-—-brace-expansion-with-each" aria-hidden="true">#</a> Pattern 10 — Brace expansion with <code>--each</code></h2><p>Combine brace expansion and <code>--each</code> to fill every directory level in a branching tree.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo --each\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── <span class="token punctuation">)</span> R a Y A .txt\n    ├── H t <span class="token number">8</span> <span class="token number">9</span> h .txt\n    ├── bar\n    │   ├── <span class="token operator">!</span> + w <span class="token number">2</span> q .txt\n    │   ├── , <span class="token punctuation">)</span> R <span class="token punctuation">;</span> c .txt\n    │   └── piyo\n    │       ├── % U <span class="token number">2</span> P L .txt\n    │       └── <span class="token number">5</span> R J j c .txt\n    └── foo\n        ├── $ A P H _ .txt\n        ├── J Z d &#39; a .txt\n        └── piyo\n            ├── <span class="token builtin class-name">:</span> L w <span class="token operator">&amp;</span> I .txt\n            └── A e @ j <span class="token operator">&amp;</span> .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><hr><h2 id="pattern-11-—-images-into-multiple-directories" tabindex="-1"><a class="header-anchor" href="#pattern-11-—-images-into-multiple-directories" aria-hidden="true">#</a> Pattern 11 — Images into multiple directories</h2><p>Place dummy images into several directories using brace expansion — great for building a front-end asset structure.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg -s 800x600 images/<span class="token punctuation">{</span>pc,sp,tablet<span class="token punctuation">}</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── images\n    ├── pc\n    │   ├── 800x600_1.jpg\n    │   ├── 800x600_2.jpg\n    │   └── 800x600_3.jpg\n    ├── sp\n    │   ├── 800x600_1.jpg\n    │   ├── 800x600_2.jpg\n    │   └── 800x600_3.jpg\n    └── tablet\n        ├── 800x600_1.jpg\n        ├── 800x600_2.jpg\n        └── 800x600_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><hr><h2 id="pattern-12-—-special-character-file-names" tabindex="-1"><a class="header-anchor" href="#pattern-12-—-special-character-file-names" aria-hidden="true">#</a> Pattern 12 — Special character file names</h2><h3 id="symbol-free-names" tabindex="-1"><a class="header-anchor" href="#symbol-free-names" aria-hidden="true">#</a> Symbol-free names</h3><p>Use <code>--no-symbol</code> to generate alphanumeric-only file names.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --no-symbol\n$ tree\n<span class="token builtin class-name">.</span>\n├── Q5aocxH9uI.txt\n├── TfxZIic3Rg.txt\n└── ucmiz657Ae.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="names-with-spaces" tabindex="-1"><a class="header-anchor" href="#names-with-spaces" aria-hidden="true">#</a> Names with spaces</h3><p>Use <code>--with-whitespace</code> to include spaces — useful for testing how your app handles paths with spaces.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --with-whitespace\n$ tree\n<span class="token builtin class-name">.</span>\n├── J L $ A <span class="token punctuation">(</span> .txt\n├── T w N V c .txt\n└── V n <span class="token number">0</span> <span class="token punctuation">)</span> Z .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="names-with-2-byte-japanese-characters" tabindex="-1"><a class="header-anchor" href="#names-with-2-byte-japanese-characters" aria-hidden="true">#</a> Names with 2-byte (Japanese) characters</h3><p>Use <code>--zenkaku</code> to include Japanese characters — useful for testing multibyte filename handling.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --zenkaku\n$ tree\n<span class="token builtin class-name">.</span>\n├── 3aしにmう.txt\n├── Xたれ9かi.txt\n└── ゆBwはZ1.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="pattern-13-—-preview-with-cold-run" tabindex="-1"><a class="header-anchor" href="#pattern-13-—-preview-with-cold-run" aria-hidden="true">#</a> Pattern 13 — Preview with <code>--cold-run</code></h2><p>Not sure what will be created? Add <code>--cold-run</code> to preview the output tree without touching the filesystem.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo --each --cold-run\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── 100x100_1.jpg\n    ├── 100x100_2.jpg\n    ├── 100x100_3.jpg\n    ├── bar\n    │   ├── 100x100_1.jpg\n    │   ├── 100x100_2.jpg\n    │   ├── 100x100_3.jpg\n    │   └── piyo\n    │       ├── 100x100_1.jpg\n    │       ├── 100x100_2.jpg\n    │       └── 100x100_3.jpg\n    └── foo\n        ├── 100x100_1.jpg\n        ├── 100x100_2.jpg\n        ├── 100x100_3.jpg\n        └── piyo\n            ├── 100x100_1.jpg\n            ├── 100x100_2.jpg\n            └── 100x100_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><p>Once you are happy with the preview, remove <code>--cold-run</code> and run the same command for real.</p><hr><h2 id="options-reference" tabindex="-1"><a class="header-anchor" href="#options-reference" aria-hidden="true">#</a> Options reference</h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-h</code>, <code>--help</code></td><td>Show help and exit</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td>Show version and exit</td></tr><tr><td><code>-n</code>, <code>--number</code></td><td>Number of files to create (default: 1)</td></tr><tr><td><code>-e</code>, <code>--ext</code></td><td>File extension (default: <code>txt</code>)</td></tr><tr><td><code>-s</code>, <code>--size</code></td><td>Image size in <code>WxH</code> format (default: <code>100x100</code>). Image formats only.</td></tr><tr><td><code>-w</code>, <code>--with-whitespace</code></td><td>Include spaces in file names</td></tr><tr><td><code>-z</code>, <code>--zenkaku</code></td><td>Include 2-byte (Japanese) characters in file names</td></tr><tr><td><code>--no-symbol</code></td><td>Exclude symbol characters from file names</td></tr><tr><td><code>--each</code></td><td>Create files in every intermediate directory</td></tr><tr><td><code>--cold-run</code></td><td>Preview output without creating files</td></tr><tr><td><code>--verbose</code></td><td>Print debug information</td></tr></tbody></table>',66),r={},t=(0,s(3744).Z)(r,[["render",function(e,n){return a}]])},3744:(e,n)=>{n.Z=(e,n)=>{const s=e.__vccOpts||e;for(const[e,a]of n)s[e]=a;return s}}}]);